  "command": "cd /tmp/shopcart && find . -not -path './.git/*' -type f | head -100 && echo ---- && wc -l src/* test/* 2>/dev/null && echo ---- && cat AGENTS.md package.json"
}

{
  "command": "cd /tmp/shopcart && cat AGENTS.md package.json && wc -l src/**/*.js src/*.js"
}

{
  "command": "cd /tmp/shopcart && for f in src/domain/promo.js src/domain/cart.js src/domain/errors.js src/domain/money.js src/domain/loyalty.js; do echo \"=== $f\"; cat -n $f; done"
}

{
  "command": "cd /tmp/shopcart && for f in src/pricing/pricingService.js src/http/routes.js src/repo/memoryRepo.js src/index.js; do echo \"=== $f\"; cat -n $f; done"
}

