     9	/** Each rule is a predicate plus the message shown when it fails. */
    10	const SHAPE_RULES = [
    11	  [(p) => typeof p.code === 'string' && p.code.length > 0,
    12	    'code must be a non-empty string'],
    13	  [(p) => Number.isInteger(p.percentOff) && p.percentOff >= 1 && p.percentOff <= 100,
    14	    'percentOff must be an integer from 1 to 100'],
    15	  [(p) => Number.isInteger(p.maxUses) && p.maxUses >= 1,
    16	    'maxUses must be a positive integer'],
    17	  [(p) => Number.isInteger(p.uses) && p.uses >= 0,
    18	    'uses must not be negative'],
    19	  [(p) => !Number.isNaN(Date.parse(p.expiresAt)),
    20	    'expiresAt must be an ISO timestamp'],
    21	];
    22	
    23	/** Validate the stored record before trusting it. Add a rule by adding a row. */
    24	function assertShape(promo) {
    25	  if (!promo || typeof promo !== 'object') {
    26	    throw new DomainError('INVALID_PROMO', 'promo record is missing');
    27	  }
    28	  for (const [isValid, why] of SHAPE_RULES) {
    29	    if (!isValid(promo)) {
    30	      throw new DomainError('INVALID_PROMO', `promo ${promo.code}: ${why}`);
    31	    }
    32	  }
    33	}
    34	
    35	/**
    36	 * Throw unless the promo may be applied at `now`.
    37	 * Fails closed: a clock that is not a finite timestamp is an error, never a pass.
    38	 * @param {Promo} promo
    39	 * @param {number} now epoch milliseconds
    40	 */
    41	function assertUsable(promo, now) {
    42	  assertShape(promo);
    43	  if (!Number.isFinite(now)) {
    44	    throw new DomainError('INVALID_TIME', 'now must be a finite epoch timestamp');
    45	  }
    46	  if (now >= Date.parse(promo.expiresAt)) {
    47	    throw new DomainError('PROMO_EXPIRED', `promo ${promo.code} expired at ${promo.expiresAt}`);
    48	  }
    49	  if (promo.uses >= promo.maxUses) {
    50	    throw new DomainError('PROMO_EXHAUSTED', `promo ${promo.code} has reached ${promo.maxUses} uses`);
    51	  }
    52	}
    53	
    54	/**
    55	 * Discount in cents. Bounded by the subtotal because `percentOff` is validated
    56	 * to 1..100 — the shape rule, not a clamp, is what enforces AC7.
    57	 * @param {number} subtotalCents
    58	 * @param {Promo} promo
    59	 */
    60	function discountFor(subtotalCents, promo) {
    61	  assertShape(promo);
    62	  return percentOf(subtotalCents, promo.percentOff);
    63	}
    64	
    65	/** Normalise a submitted code: trim and upper-case, so 'save10 ' matches SAVE10. */
    66	function normaliseCode(raw) {
    67	  if (typeof raw !== 'string' || raw.trim() === '') {
    68	    throw new DomainError('INVALID_PROMO_CODE', 'promo code must be a non-empty string');
    69	  }
    70	  return raw.trim().toUpperCase();
    71	}
