     2	const { percentOf } = require('./money');
     3	
     4	/**
     5	 * Customer loyalty tiers. Pure: the rates are business rules, not stored data,
     6	 * so there is no repo, no I/O and no clock here.
     7	 * @typedef {'bronze'|'silver'|'gold'} Tier
     8	 */
