    10	/** Percentage off the subtotal, by tier. Adding a tier is one row. */
    11	const TIER_PERCENTS = Object.freeze({ bronze: 0, silver: 2, gold: 5 });
    12	
    13	const KNOWN_TIERS = Object.keys(TIER_PERCENTS);
    14	
    15	/**
    16	 * Normalise a submitted tier: trim and lower-case, so ' Gold ' matches gold.
    17	 * Fails closed: anything that is not a known tier raises `UNKNOWN_TIER` rather
    18	 * than defaulting, because pricing an unrecognised customer at full price is the
    19	 * silent failure this feature exists to prevent.
    20	 * @param {unknown} raw
    21	 * @returns {Tier}
    22	 */
    23	function normaliseTier(raw) {
    24	  const tier = typeof raw === 'string' ? raw.trim().toLowerCase() : '';
    25	  if (!Object.prototype.hasOwnProperty.call(TIER_PERCENTS, tier)) {
    26	    throw new DomainError('UNKNOWN_TIER',
    27	      `loyalty tier ${JSON.stringify(raw)} is not one of ${KNOWN_TIERS.join(', ')}`);
    28	  }
    29	  return tier;
    30	}
    31	
    32	/**
    33	 * Discount in cents for a tier, taken from the subtotal. Bounded by the subtotal
    34	 * because every rate is well under 100.
    35	 * @param {number} subtotalCents
    36	 * @param {Tier} tier
    37	 */
    38	function discountFor(subtotalCents, tier) {
    39	  return percentOf(subtotalCents, TIER_PERCENTS[normaliseTier(tier)]);
    40	}
    41	
    42	module.exports = { TIER_PERCENTS, normaliseTier, discountFor };

