=== src/pricing/pricingService.js
     1	const { subtotal } = require('../domain/cart');
     2	const { percentOf } = require('../domain/money');
     3	const { assertUsable, discountFor, normaliseCode } = require('../domain/promo');
     4	const { normaliseTier, discountFor: tierDiscountFor } = require('../domain/loyalty');
     5	const { DomainError } = require('../domain/errors');
     6	
     7	const TAX_PERCENT = 8;
     8	const FREE_SHIPPING_THRESHOLD_CENTS = 5000;
     9	const SHIPPING_FLAT_CENTS = 599;
    10	const MAX_DISCOUNT_PERCENT = 30;
    11	
    12	/** Look up a submitted code and check it may be used. */
    13	function resolvePromo(rawCode, { promoRepo, now }) {
    14	  if (!promoRepo) {
    15	    // Programmer error, not a client error: fail loudly rather than 400.
    16	    throw new Error('priceCart: a promoCode was supplied but no promoRepo was configured');
    17	  }
    18	  const code = normaliseCode(rawCode);
    19	  const promo = promoRepo.findById(code);
    20	  if (!promo) {
    21	    throw new DomainError('PROMO_NOT_FOUND', `promo ${code} does not exist`);
    22	  }
    23	  assertUsable(promo, now);
    24	  return promo;
    25	}
    26	
    27	/**
    28	 * The promo's share of the discount, taken from the original subtotal.
    29	 * An absent code is worth nothing; an unusable one is an error, never a silent skip.
    30	 * @returns {{label: ?string, cents: number}}
    31	 */
    32	function promoDiscount(rawCode, subtotalCents, deps) {
    33	  if (rawCode === undefined || rawCode === null) {
    34	    return { label: null, cents: 0 };
    35	  }
    36	  const promo = resolvePromo(rawCode, deps);
    37	  return { label: promo.code, cents: discountFor(subtotalCents, promo) };
    38	}
    39	
    40	/**
    41	 * The tier's share of the discount, taken from the original subtotal.
    42	 * Only an omitted field means "no tier": any value that is present must be a known
    43	 * tier, so a customer record that failed to load cannot be priced at full price.
    44	 * @returns {{label: ?string, cents: number}}
    45	 */
    46	function tierDiscount(rawTier, subtotalCents) {
    47	  if (rawTier === undefined) {
    48	    return { label: null, cents: 0 };
    49	  }
    50	  const tier = normaliseTier(rawTier);
    51	  return { label: tier, cents: tierDiscountFor(subtotalCents, tier) };
    52	}
    53	
    54	/**
    55	 * Price a cart. Order of operations: subtotal -> discount -> shipping -> tax,
    56	 * so both shipping and tax follow the amount actually charged.
    57	 *
    58	 * The loyalty tier and the promo code stack: each is computed from the original
    59	 * subtotal, then summed and capped at MAX_DISCOUNT_PERCENT of that subtotal.
    60	 * `tierDiscountCents` and `promoDiscountCents` report the two components before
    61	 * the cap; `discountCents` is what was actually applied.
    62	 *
    63	 * @param {{lines: Array, promoCode?: string, loyaltyTier?: string}} cart
    64	 * @param {{promoRepo?: object, now?: number}} [deps]
    65	 * @returns {{subtotalCents:number, discountCents:number, tierDiscountCents:number,
    66	 *            promoDiscountCents:number, shippingCents:number, taxCents:number,
    67	 *            totalCents:number, appliedPromoCode:?string, loyaltyTier:?string}}
    68	 */
    69	function priceCart(cart, deps = {}) {
    70	  const sub = subtotal(cart.lines);
    71	  const now = deps.now === undefined || deps.now === null ? Date.now() : deps.now;
    72	
    73	  const tier = tierDiscount(cart.loyaltyTier, sub);
    74	  const promo = promoDiscount(cart.promoCode, sub, { promoRepo: deps.promoRepo, now });
    75	  const discountCents = Math.min(tier.cents + promo.cents, percentOf(sub, MAX_DISCOUNT_PERCENT));
    76	
    77	  const discounted = sub - discountCents;
    78	  const shipping = discounted >= FREE_SHIPPING_THRESHOLD_CENTS ? 0 : SHIPPING_FLAT_CENTS;
    79	  const tax = percentOf(discounted, TAX_PERCENT);
    80	
    81	  return {
    82	    subtotalCents: sub,
    83	    discountCents,
    84	    tierDiscountCents: tier.cents,
    85	    promoDiscountCents: promo.cents,
    86	    shippingCents: shipping,
    87	    taxCents: tax,
    88	    totalCents: discounted + shipping + tax,
    89	    appliedPromoCode: promo.label,
    90	    loyaltyTier: tier.label,
    91	  };
    92	}
    93	
    94	/**
    95	 * Price a cart and consume one use of the promo, if any was applied.
    96	 * The repo write lives here because pricing owns the repo (AGENTS.md layering).
    97	 * The update is conditional, so a concurrent redemption cannot be lost.
    98	 */
    99	function priceAndRedeem(cart, deps = {}) {
   100	  const price = priceCart(cart, deps);
   101	  if (price.appliedPromoCode) {
   102	    const current = deps.promoRepo.findById(price.appliedPromoCode);
   103	    const updated = deps.promoRepo.replaceIfUnchanged(
   104	      price.appliedPromoCode, current, { ...current, uses: current.uses + 1 },
   105	    );
   106	    if (!updated) {
   107	      throw new DomainError('PROMO_CONTENDED', `promo ${price.appliedPromoCode} was updated concurrently; retry`);
   108	    }
   109	  }
   110	  return price;
   111	}
   112	
   113	module.exports = {
   114	  priceCart, priceAndRedeem,
   115	  TAX_PERCENT, FREE_SHIPPING_THRESHOLD_CENTS, SHIPPING_FLAT_CENTS, MAX_DISCOUNT_PERCENT,
   116	};
