     1	const { priceCart, priceAndRedeem } = require('../pricing/pricingService');
     2	const { DomainError } = require('../domain/errors');
     3	
     4	/**
     5	 * Build a request handler over its dependencies.
     6	 * @param {{promoRepo?: object, now?: () => number}} [deps]
     7	 */
     8	function createHandler(deps = {}) {
     9	  return function handle(method, path, body) {
    10	    try {
    11	      if (method === 'POST' && path === '/price') {
    12	        const price = priceAndRedeem(body, {
    13	          promoRepo: deps.promoRepo,
    14	          now: deps.now ? deps.now() : undefined,
    15	        });
    16	        return { status: 200, body: price };
    17	      }
    18	      return { status: 404, body: { error: 'not_found' } };
    19	    } catch (err) {
    20	      if (err instanceof DomainError) {
    21	        return { status: 400, body: { error: err.code, message: err.message } };
    22	      }
    23	      throw err;
    24	    }
    25	  };
    26	}
    27	
    28	/** Default handler, kept for existing callers. Prices only; no promo store. */
    29	const handle = createHandler();
    30	
    31	module.exports = { createHandler, handle };
