     1	/** Tiny in-memory store. Swap for a real one behind the same interface. */
     2	class MemoryRepo {
     3	  constructor(seed = {}) {
     4	    this.items = new Map(Object.entries(seed));
     5	  }
     6	
     7	  findById(id) {
     8	    return this.items.get(id) || null;
     9	  }
    10	
    11	  save(id, value) {
    12	    this.items.set(id, value);
    13	    return value;
    14	  }
    15	
    16	  /**
    17	   * Compare-and-set: replace `id` only if it still holds `expected`.
    18	   * Returns the stored value, or null when another writer got there first.
    19	   * A real store implements this as a conditional update; callers must not
    20	   * read-then-write, or concurrent redemptions are lost.
    21	   */
    22	  replaceIfUnchanged(id, expected, next) {
    23	    if (this.items.get(id) !== expected) {
    24	      return null;
    25	    }
    26	    this.items.set(id, next);
    27	    return next;
    28	  }
    29	}
    30	
    31	module.exports = { MemoryRepo };
