* The loyalty tier and the promo code stack: each is computed from the original
* subtotal, then summed and capped at MAX_DISCOUNT_PERCENT of that subtotal.
* `tierDiscountCents` and `promoDiscountCents` report the two components before
* the cap; `discountCents` is what was actually applied.
*
 const tier = tierDiscount(cart.loyaltyTier, sub);
 const promo = promoDiscount(cart.promoCode, sub, { promoRepo: deps.promoRepo, now });
 const discountCents = Math.min(tier.cents + promo.cents, percentOf(sub, MAX_DISCOUNT_PERCENT));

 assert.deepStrictEqual(Object.keys(r).sort(), [
   'appliedPromoCode', 'discountCents', 'loyaltyTier', 'promoDiscountCents', 'shippingCents',
   'subtotalCents', 'taxCents', 'tierDiscountCents', 'totalCents',
 ], 'no internal promo record leaks into the public shape');

